#define _XOPEN_SOURCE 600

#include <ctime>
#include <vector>
#include <iostream>
#include "CRC64.h"

using namespace std;
int main(int argc, char *argv[]) {
  int ntests = 10;
  if (argc > 1) ntests = atoi(argv[1]);

  int seed = 5;
  if (argc > 2) seed = atoi(argv[2]);

  int max_test_length = 2097152;
  if (argc > 3) max_test_length = atoi(argv[3]);

  cout << "Running " << ntests << " tests with seed " << seed << endl;

  srand48(seed);

#ifdef __bgp__
#define THE_CLOCK CLOCK_REALTIME
#else
#define THE_CLOCK CLOCK_THREAD_CPUTIME_ID
#endif

  double tot_time = 0, tot_bytes = 0;

  int ntest = 0;
  while (++ntest <= ntests) {
    cout << ntest << " ";

    size_t test_length = (size_t) (max_test_length*(drand48()+1));
    cout << test_length << " ";

    vector<unsigned char> buffer(test_length);

    for (size_t i = 0; i < test_length; ++i) {
      buffer[i] = (unsigned char) (255*drand48());
    }

    timespec b_start, b_end;
    clock_gettime(THE_CLOCK, &b_start);

    uint64_t cs = crc64_omp(&buffer[0], test_length);

    clock_gettime(THE_CLOCK, &b_end);
    double b_time = (b_end.tv_sec - b_start.tv_sec);
    b_time += 1e-9*(b_end.tv_nsec - b_start.tv_nsec);

    if (ntest > 1) {
      tot_time += b_time;
      tot_bytes += test_length;
    }

    // Copy the buffer and append the check bytes.
    size_t tlend = 8;
    buffer.resize(test_length + tlend, 0);
    crc64_invert(cs, &buffer[test_length]);

    string pass("pass"), fail("fail");
    uint64_t csc = crc64(&buffer[0], test_length+tlend);
    cout << ((csc == (uint64_t) -1) ? pass : fail) << " ";

    size_t div_pt = (size_t) (test_length*drand48());
    uint64_t cs1 = crc64(&buffer[0], div_pt);
    uint64_t cs2 = crc64(&buffer[div_pt], test_length - div_pt);
    csc = crc64_combine(cs1, cs2, test_length - div_pt);
    cout << ((csc == cs) ? pass : fail);

    cout << endl;
  }

  cout << (tot_bytes/(1024*1024))/tot_time << " MB/s" << endl;

  return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <chrono>
#include <omp.h>

#define CHUNK_S 4096

int main(int argc, char* argv[]) {
  if (argc != 4) {
    printf("Usage: %s <#samples> <#voxels> <verify>\n", argv[0]);
    exit(1);
  }
  const int samples = atoi(argv[1]); // in the order of 100000
  const int voxels = atoi(argv[2]);  // cube(128)/2097152
  const int verify = atoi(argv[3]);
  const int sampleSize = samples * sizeof(float);
  const int voxelSize = voxels * sizeof(float);

  float *h_rmu = (float*) malloc (voxelSize);
  float *h_imu = (float*) malloc (voxelSize);
  float *h_kx = (float*) malloc (voxelSize);
  float *h_ky = (float*) malloc (voxelSize);
  float *h_kz = (float*) malloc (voxelSize);

  float *h_rfhd = (float*) malloc (sampleSize);
  float *h_ifhd = (float*) malloc (sampleSize);
  float *h_x = (float*) malloc (sampleSize);
  float *h_y = (float*) malloc (sampleSize);
  float *h_z = (float*) malloc (sampleSize);

  // For device results
  float *rfhd = (float*) malloc (sampleSize);
  float *ifhd = (float*) malloc (sampleSize);

  srand(2);
  for (int i = 0; i < samples; i++) {
    rfhd[i] = h_rfhd[i] = (float)i/samples;
    ifhd[i] = h_ifhd[i] = (float)i/samples;
    h_x[i] = 0.3f + (rand()%2 ? 0.1 : -0.1);
    h_y[i] = 0.2f + (rand()%2 ? 0.1 : -0.1);
    h_z[i] = 0.1f + (rand()%2 ? 0.1 : -0.1);
  }

  for (int i = 0; i < voxels; i++) {
    h_rmu[i] = (float)i/voxels;
    h_imu[i] = (float)i/voxels;
    h_kx[i] = 0.1f + (rand()%2 ? 0.1 : -0.1);
    h_ky[i] = 0.2f + (rand()%2 ? 0.1 : -0.1);
    h_kz[i] = 0.3f + (rand()%2 ? 0.1 : -0.1);
  }

  printf("Run FHd on a device\n");

  #pragma omp target data map(to: h_rmu[0:voxels],\
                                  h_imu[0:voxels],\
                                  h_kx[0:voxels],\
                                  h_ky[0:voxels],\
                                  h_kz[0:voxels],\
                                  h_x[0:samples],\
                                  h_y[0:samples],\
                                  h_z[0:samples]) \
                          map(tofrom: rfhd[0:samples],\
                                      ifhd[0:samples])
  {
    auto start = std::chrono::steady_clock::now();

    #pragma omp target teams distribute parallel for
    for (int n = 0; n < samples; n++) {
      float r = rfhd[n];
      float i = ifhd[n];
      float xn = h_x[n];
      float yn = h_y[n];
      float zn = h_z[n];
      #pragma omp parallel for simd reduction(+:r,i)
      for (int m = 0; m < voxels; m++) {
        float e = 2.f * (float)M_PI * 
                  (h_kx[m] * xn + h_ky[m] * yn + h_kz[m] * zn);
        float c = cosf(e);
        float s = sinf(e);
        r += h_rmu[m] * c - h_imu[m] * s;
        i += h_imu[m] * c + h_rmu[m] * s;
      }
      rfhd[n] = r;
      ifhd[n] = i;   
    }

    auto end = std::chrono::steady_clock::now();
    auto time = std::chrono::duration_cast<std::chrono::nanoseconds>(end - start).count();
    printf("Device execution time %f (s)\n", time * 1e-9f);
  }

  if (verify) {
    printf("Computing root mean square error between host and device results.\n");
    printf("This will take a while..\n");

    #pragma omp parallel for 
    for (int n = 0; n < samples; n++) {
      float r = h_rfhd[n];
      float i = h_ifhd[n];
      #pragma omp parallel for simd reduction(+:r,i)
      for (int m = 0; m < voxels; m++) {
        float e = 2.f * (float)M_PI * 
                  (h_kx[m] * h_x[n] + h_ky[m] * h_y[n] + h_kz[m] * h_z[n]);
        float c = cosf(e);
        float s = sinf(e);
        r += h_rmu[m] * c - h_imu[m] * s;
        i += h_imu[m] * c + h_rmu[m] * s;
      }
      h_rfhd[n] = r;
      h_ifhd[n] = i;   
    }

    float err = 0.f;
    for (int i = 0; i < samples; i++) {
      err += (h_rfhd[i] - rfhd[i]) * (h_rfhd[i] - rfhd[i]) +
             (h_ifhd[i] - ifhd[i]) * (h_ifhd[i] - ifhd[i]) ;
    }
    printf("RMSE = %f\n", sqrtf(err / (2*samples)));
  }

  free(h_rmu);
  free(h_imu);
  free(h_kx);
  free(h_ky);
  free(h_kz);
  free(h_rfhd);
  free(h_ifhd);
  free(rfhd);
  free(ifhd);
  free(h_x);
  free(h_y);
  free(h_z);

  return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <algorithm>
#include <chrono>
#include <random>
#include <vector>
#include <omp.h>

int main(int argc, char **argv) {
  if (argc != 4) {
    printf("Usage: %s <number of elements> <block size> <repeat>\n", argv[0]);
    return 1;
  }
  const int num_elems = atoi(argv[1]);
  const int block_size = atoi(argv[2]);
  const int repeat = atoi(argv[3]);

  std::vector<int> input (num_elems);
  std::vector<int> output (num_elems);

  // Generate input data.
  for (int i = 0; i < num_elems; i++) {
    input[i] = i - num_elems / 2;
  }

  std::mt19937 g;
  g.seed(19937);
  std::shuffle(input.begin(), input.end(), g);

  int *data_to_filter = input.data();
  int *filtered_data = output.data();
  int nres[1];

  #pragma omp target data map(to: data_to_filter[0:num_elems]) \
                          map(from: nres[0:1]) \
                          map(from: filtered_data[0:num_elems])
  {
    auto start = std::chrono::steady_clock::now();

    for (int i = 0; i < repeat; i++) {
      nres[0] = 0;
      #pragma omp target update to (nres[0:1]) // need to reset on device 

      #pragma omp target teams num_teams((num_elems+block_size-1)/block_size) \
      thread_limit(block_size) 
      {
        int l_n;
        #pragma omp parallel 
        {
          int i = omp_get_team_num() * omp_get_num_threads() + omp_get_thread_num() ;
          if (omp_get_thread_num() == 0)
            l_n = 0;
          #pragma omp barrier
          int d, pos;

          if(i < num_elems) {
            d = data_to_filter[i];
            if(d > 0) {
              #pragma omp atomic capture
              pos = l_n++;
            }
          }
          #pragma omp barrier

          // leader increments the global counter
          if (omp_get_thread_num() == 0) {
            //l_n = atomicAdd(nres, l_n);
             int old;
             #pragma omp atomic capture
             {
                old = nres[0];
                nres[0] += l_n; 
             }
             l_n = old;
          }
          #pragma omp barrier

          // threads with true predicates write their elements
          if(i < num_elems && d > 0) {
            pos += l_n; // increment local pos by global counter
            filtered_data[pos] = d;
          }
          #pragma omp barrier
        }
      }
    }

    auto end = std::chrono::steady_clock::now();
    auto time = std::chrono::duration_cast<std::chrono::nanoseconds>(end - start).count();
    printf("Average kernel execution time %lf (ms)\n", (time * 1e-6) / repeat);
  }

  std::vector<int> h_output (num_elems);

  // Generate host output with host filtering code.
  int h_flt_count = 0;
  for (int i = 0; i < num_elems; i++) {
    if (input[i] > 0) {
      h_output[h_flt_count++] = input[i];
    }
  }

  // Verify
  std::sort(h_output.begin(), h_output.begin() + h_flt_count);
  std::sort(output.begin(), output.begin() + nres[0]);

  bool equal = (h_flt_count == nres[0]) && 
               std::equal(h_output.begin(),
                          h_output.begin() + h_flt_count, output.begin());

  printf("\nFilter using shared memory %s \n",
         equal ? "PASS" : "FAIL");

  return 0;
}

#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>
#include <sys/time.h>
#include <math.h>
#include <utility>
#include <omp.h>

#define NTX 16
#define NTY 16

double stop_watch(double t0)
{
  double time;
  struct timeval t;
  gettimeofday(&t, NULL);
  time = t.tv_sec * 1e6 + t.tv_usec;
  return time-t0;
}

void usage(char *argv[]) {
  fprintf(stderr, " Usage: %s LX LY NITER\n", argv[0]);
  return;
}

void reference(float *out, const float *in, const float delta, const float norm, const int Lx, const int Ly)
{
  #pragma omp parallel for collapse(2)
  for (int y = 0; y < Ly; y++) {
    for (int x = 0; x < Lx; x++) {
      int v00 = y*Lx + x;
      int v0p = y*Lx + (x + 1)%Lx;
      int v0m = y*Lx + (Lx + x - 1)%Lx;
      int vp0 = ((y+1)%Ly)*Lx + x;
      int vm0 = ((Ly+y-1)%Ly)*Lx + x;
      out[v00] = norm*in[v00] + delta*(in[v0p] + in[v0m] + in[vp0] + in[vm0]);
    }
  }
}

void dev_lapl_iter(float *out, const float *in, const float delta, const float norm, const int Lx, const int Ly)
{
  #pragma omp target teams distribute parallel for collapse(2) thread_limit(256)
  for (int y = 0; y < Ly; y++) {
    for (int x = 0; x < Lx; x++) {
      int v00 = y*Lx + x;
      int v0p = y*Lx + (x + 1)%Lx;
      int v0m = y*Lx + (Lx + x - 1)%Lx;
      int vp0 = ((y+1)%Ly)*Lx + x;
      int vm0 = ((Ly+y-1)%Ly)*Lx + x;
      out[v00] = norm*in[v00] + delta*(in[v0p] + in[v0m] + in[vp0] + in[vm0]);
    }
  }
}

int main(int argc, char *argv[]) {
  /* Check the number of command line arguments */
  if(argc != 4) {
    usage(argv);
    exit(1);
  }
  /* The length of the array in x and y is read from the command
     line */
  int Lx = atoi(argv[1]);
  int Ly = atoi(argv[2]);
  if (Lx % NTX != 0 ||  Ly % NTY != 0) {
    printf("Array length LX and LY must be a multiple of block size %d and %d, respectively\n",
          NTX, NTY);
    exit(1);
  }
  /* The number of iterations */
  int niter = atoi(argv[3]);
  assert(niter >= 1);

  /* Fixed "sigma" */
  const float sigma = 0.01;
  const float xdelta = sigma / (1.0+4.0*sigma);
  const float xnorm = 1.0/(1.0+4.0*sigma);

  printf(" Ly,Lx = %d,%d\n", Ly, Lx);
  printf(" niter = %d\n", niter);

  /* Allocate the buffer for the data */
  srand(123);
  float *buffer = (float*) malloc(sizeof(float)*Lx*Ly);
  float *h_out = (float*) malloc(sizeof(float)*Lx*Ly);
  float *h_in  = (float*) malloc(sizeof(float)*Lx*Ly);

  int i, j, x, y;
  for (i = 0; i < Lx; i += 16) {
    x = rand() % Lx;
    for (j = 0; j < Ly; j++)
       buffer[x + j*Lx] = 1.f;
  }
  for (i = 0; i < Ly; i += 16) {
    y = rand() % Ly;
    for (j = 0; j < Lx; j++)
       buffer[j + y*Lx] = 1.f;
  }
  memcpy(h_in, buffer, sizeof(float)*Lx*Ly);

  for(i=0; i<niter; i++) {
    reference (h_out, h_in, xdelta, xnorm, Lx, Ly);
    std::swap(h_out, h_in);
  }

  float *d_out = (float*) malloc(sizeof(float)*Lx*Ly);
  float *d_in  = (float*) malloc(sizeof(float)*Lx*Ly);
  memcpy(d_in, buffer, sizeof(float)*Lx*Ly);

  double t0;
  /* Fixed number of threads per block (in x- and y-direction), number
     of blocks per direction determined by dimensions Lx, Ly */
  #pragma omp target data map (tofrom: d_in[0:Lx*Ly]) map(alloc: d_out[0:Lx*Ly])
  {
    t0 = stop_watch(0);
    for(i=0; i<niter; i++) {
      dev_lapl_iter(d_out, d_in, xdelta, xnorm, Lx, Ly);
      std::swap(d_out, d_in);
    }
    t0 = stop_watch(t0)/(double)niter;
  }

  printf("Device: iters = %8d, (Lx,Ly) = %6d, %6d, t = %8.1f usec/iter, BW = %6.3f GB/s, P = %6.3f Gflop/s\n",
  	 niter, Lx, Ly, t0,
  	 Lx*Ly*sizeof(float)*2.0/(t0*1.0e3),
  	 (Lx*Ly*6.0)/(t0*1.0e3));

  // verification
  bool ok = true;
  for (i = 0; i < Lx*Ly; i++) {
    // choose 1e-2 because the error rate increases with the iteration from 1 to 100000
    if ( fabs(h_in[i] - d_in[i]) > 1e-2 ) {
      printf("Mismatch at %d cpu=%f gpu=%f\n", i, h_in[i], d_in[i]);
      ok = false;
      break;
    }
  }
  printf("%s\n", ok ? "PASS" : "FAIL");

  free(buffer);
  free(h_out);
  free(h_in);
  free(d_in);
  free(d_out);
  return 0;
}

/** GPU Laplace solver using optimized red-black Gauss–Seidel with SOR solver
 *
 * Solves Laplace's equation in 2D (e.g., heat conduction in a rectangular plate)
 * on GPU using OpenMP with the red-black Gauss–Seidel with sucessive overrelaxation
 * (SOR) that has been "optimized". This means that the red and black kernels 
 * only loop over their respective cells, instead of over all cells and skipping
 * even/odd cells. This requires separate arrays for red and black cells.
 * 
 * Boundary conditions:
 * T = 0 at x = 0, x = L, y = 0
 * T = TN at y = H
 */

#include <stdlib.h>
#include <stdio.h>
#include <math.h>
#include "timer.h"

/** Problem size along one side; total number of cells is this squared */
#define NUM 1024

// block size
#define BLOCK_SIZE 256

#define Real float
#define ZERO 0.0f
#define ONE 1.0f
#define TWO 2.0f

/** SOR relaxation parameter */
const Real omega = 1.85f;

#include "reference.h"

/** Function to evaluate coefficient matrix and right-hand side vector.
 * 
 * \param[in]   rowmax   number of rows
 * \param[in]   colmax   number of columns
 * \param[in]   th_cond  thermal conductivity
 * \param[in]   dx       grid size in x dimension (uniform)
 * \param[in]   dy       grid size in y dimension (uniform)
 * \param[in]   width    width of plate (z dimension)
 * \param[in]   TN       temperature at top boundary
 * \param[out]  aP       array of self coefficients
 * \param[out]  aW       array of west neighbor coefficients
 * \param[out]  aE       array of east neighbor coefficients
 * \param[out]  aS       array of south neighbor coefficients
 * \param[out]  aN       array of north neighbor coefficients
 * \param[out]  b        right-hand side array
 */
void fill_coeffs (int rowmax, int colmax, Real th_cond, Real dx, Real dy,
    Real width, Real TN, Real * aP, Real * aW, Real * aE, 
    Real * aS, Real * aN, Real * b)
{
  int col, row;
  for (col = 0; col < colmax; ++col) {
    for (row = 0; row < rowmax; ++row) {
      int ind = col * rowmax + row;

      b[ind] = ZERO;
      Real SP = ZERO;

      if (col == 0) {
        // left BC: temp = 0
        aW[ind] = ZERO;
        SP = -TWO * th_cond * width * dy / dx;
      } else {
        aW[ind] = th_cond * width * dy / dx;
      }

      if (col == colmax - 1) {
        // right BC: temp = 0
        aE[ind] = ZERO;
        SP = -TWO * th_cond * width * dy / dx;
      } else {
        aE[ind] = th_cond * width * dy / dx;
      }

      if (row == 0) {
        // bottom BC: temp = 0
        aS[ind] = ZERO;
        SP = -TWO * th_cond * width * dx / dy;
      } else {
        aS[ind] = th_cond * width * dx / dy;
      }

      if (row == rowmax - 1) {
        // top BC: temp = TN
        aN[ind] = ZERO;
        b[ind] = TWO * th_cond * width * dx * TN / dy;
        SP = -TWO * th_cond * width * dx / dy;
      } else {
        aN[ind] = th_cond * width * dx / dy;
      }

      aP[ind] = aW[ind] + aE[ind] + aS[ind] + aN[ind] - SP;
    } // end for row
  } // end for col
} // end fill_coeffs

/** Main function that solves Laplace's equation in 2D (heat conduction in plate)
 * 
 * Contains iteration loop for red-black Gauss-Seidel with SOR GPU kernels
 */
int main (void) {

  // size of plate
  Real L = 1.0;
  Real H = 1.0;
  Real width = 0.01;

  // thermal conductivity
  Real th_cond = 1.0;

  // temperature at top boundary
  Real TN = 1.0;

  // SOR iteration tolerance
  Real tol = 1.e-6;

  // number of cells in x and y directions
  // including unused boundary cells
  int num_rows = (NUM / 2) + 2;
  int num_cols = NUM + 2;
  int size_temp = num_rows * num_cols;
  int size = NUM * NUM;

  // size of cells
  Real dx = L / NUM;
  Real dy = H / NUM;

  // iterations for Red-Black Gauss-Seidel with SOR
  int iter;
  int it_max = 1e6;

  // allocate memory
  Real *aP, *aW, *aE, *aS, *aN, *b;
  Real *temp_red, *temp_black;
  Real *temp_red_ref, *temp_black_ref;

  // arrays of coefficients
  aP = (Real *) calloc (size, sizeof(Real));
  aW = (Real *) calloc (size, sizeof(Real));
  aE = (Real *) calloc (size, sizeof(Real));
  aS = (Real *) calloc (size, sizeof(Real));
  aN = (Real *) calloc (size, sizeof(Real));

  // RHS
  b = (Real *) calloc (size, sizeof(Real));

  // temperature arrays
  temp_red = (Real *) calloc (size_temp, sizeof(Real));
  temp_black = (Real *) calloc (size_temp, sizeof(Real));
  temp_red_ref = (Real *) calloc (size_temp, sizeof(Real));
  temp_black_ref = (Real *) calloc (size_temp, sizeof(Real));

  // set coefficients
  fill_coeffs (NUM, NUM, th_cond, dx, dy, width, TN, aP, aW, aE, aS, aN, b);

  int i;
  for (i = 0; i < size_temp; ++i) {
    temp_red[i] = ZERO;
    temp_black[i] = ZERO;
  }

  // residual
  Real *bl_norm_L2;

  // one for each temperature value
  int size_norm = size_temp;
  bl_norm_L2 = (Real *) calloc (size_norm, sizeof(Real));
  for (i = 0; i < size_norm; ++i) {
    bl_norm_L2[i] = ZERO;
  }

  // print problem info
  printf("Problem size: %d x %d \n", NUM, NUM);

  // iteration loop
  #pragma omp target data map(to: aP[0:size], aW[0:size], aE[0:size], aS[0:size], aN[0:size], \
                                  b[0:size], bl_norm_L2[0:size_norm]) \
                          map(tofrom: temp_red[0:size_temp], temp_black[0:size_temp])
  {
    StartTimer();

    for (iter = 1; iter <= it_max; ++iter) {

      Real norm_L2 = ZERO;

      #pragma omp target teams distribute parallel for collapse(2) num_threads(BLOCK_SIZE)
      for (int row = 1; row <= NUM/2; row++) {
        for (int col = 1; col <= NUM; col++) {
          int ind_red = col * ((NUM >> 1) + 2) + row;  					// local (red) index
          int ind = 2 * row - (col & 1) - 1 + NUM * (col - 1);	// global index

          Real temp_old = temp_red[ind_red];

          Real res = b[ind] + (aW[ind] * temp_black[row + (col - 1) * ((NUM >> 1) + 2)]
                + aE[ind] * temp_black[row + (col + 1) * ((NUM >> 1) + 2)]
                + aS[ind] * temp_black[row - (col & 1) + col * ((NUM >> 1) + 2)]
                + aN[ind] * temp_black[row + ((col + 1) & 1) + col * ((NUM >> 1) + 2)]);

          Real temp_new = temp_old * (ONE - omega) + omega * (res / aP[ind]);

          temp_red[ind_red] = temp_new;
          res = temp_new - temp_old;

          bl_norm_L2[ind_red] = res * res;
        }
      }
      // add red cell contributions to residual
      #pragma omp target teams distribute parallel for reduction(+:norm_L2)
      for (int i = 0; i < size_norm; ++i) {
        norm_L2 += bl_norm_L2[i];
      }

      #pragma omp target teams distribute parallel for collapse(2) num_threads(BLOCK_SIZE)
      for (int row = 1; row <= NUM/2; row++) {
        for (int col = 1; col <= NUM; col++) {
          int ind_black = col * ((NUM >> 1) + 2) + row; // local (black) index
          int ind = 2 * row - ((col + 1) & 1) - 1 + NUM * (col - 1); // global index

          Real temp_old = temp_black[ind_black];

          Real res = b[ind] + (aW[ind] * temp_red[row + (col - 1) * ((NUM >> 1) + 2)]
                + aE[ind] * temp_red[row + (col + 1) * ((NUM >> 1) + 2)]
                + aS[ind] * temp_red[row - ((col + 1) & 1) + col * ((NUM >> 1) + 2)]
                + aN[ind] * temp_red[row + (col & 1) + col * ((NUM >> 1) + 2)]);

          Real temp_new = temp_old * (ONE - omega) + omega * (res / aP[ind]);

          temp_black[ind_black] = temp_new;
          res = temp_new - temp_old;

          bl_norm_L2[ind_black] = res * res;
        }
      }
      // add black cell contributions to residual
      #pragma omp target teams distribute parallel for reduction(+:norm_L2)
      for (int i = 0; i < size_norm; ++i)
        norm_L2 += bl_norm_L2[i];

      // calculate residual
      norm_L2 = sqrt(norm_L2 / ((Real)size));

      if (iter % 1000 == 0) printf("%5d, %0.6f\n", iter, norm_L2);

      // if tolerance has been reached, end SOR iterations
      if (norm_L2 < tol) break;
    }

    double runtime = GetTimer();
    printf("Total time for %i iterations: %f s\n", iter, runtime / 1000.0);
  }

  // Reference
  int count = 0;

  for (iter = 1; iter <= it_max; ++iter) {
    Real norm_L2;
    norm_L2 = red_ref(aP, aW, aE, aS, aN, b, temp_black_ref, temp_red_ref);
    norm_L2 += black_ref (aP, aW, aE, aS, aN, b, temp_red_ref, temp_black_ref);
    norm_L2 = sqrt(norm_L2 / ((Real)size));
    if (norm_L2 < tol) break;
  }

  // print temperature data to file
  FILE * pfile;
  pfile = fopen("temperature.dat", "w");

  if (pfile != NULL) {
    fprintf(pfile, "#x\ty\ttemp(K)\n");

    int row, col;
    for (row = 1; row < NUM + 1; ++row) {
      for (col = 1; col < NUM + 1; ++col) {
        Real x_pos = (col - 1) * dx + (dx / 2);
        Real y_pos = (row - 1) * dy + (dy / 2);

        if ((row + col) % 2 == 0) {
          // even, so red cell
          int ind = col * num_rows + (row + (col % 2)) / 2;
          if ((temp_red[ind] - temp_red_ref[ind]) >= 1e-3f) count++;
          fprintf(pfile, "%f\t%f\t%f\n", x_pos, y_pos, temp_red[ind]);
        } else {
          // odd, so black cell
          int ind = col * num_rows + (row + ((col + 1) % 2)) / 2;
          if ((temp_black[ind] - temp_black_ref[ind]) >= 1e-3f) count++;
          fprintf(pfile, "%f\t%f\t%f\n", x_pos, y_pos, temp_black[ind]);
        }	
      }
      fprintf(pfile, "\n");
    }
  }

  fclose(pfile);
  printf("%s\n", count == 0 ? "PASS" : "FAIL");

  free(aP);
  free(aW);
  free(aE);
  free(aS);
  free(aN);
  free(b);
  free(temp_red);
  free(temp_black);
  free(temp_red_ref);
  free(temp_black_ref);
  free(bl_norm_L2);

  return 0;
}

